import{_ as t,c as n,j as e,a as l,o as _}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第六十八章 除灭对物质和精神的挂念","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/68第六十八章 除灭对物质和精神的挂念.md","filePath":"meditation/巴利文大藏经/68第六十八章 除灭对物质和精神的挂念.md"}'),r={name:"meditation/巴利文大藏经/68第六十八章 除灭对物质和精神的挂念.md"};function o(s,a,i,d,p,c){return _(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第六十八章-除灭对物质和精神的挂念",tabindex:"-1"},[l("第六十八章 除灭对物质和精神的挂念 "),e("a",{class:"header-anchor",href:"#第六十八章-除灭对物质和精神的挂念","aria-label":'Permalink to "第六十八章 除灭对物质和精神的挂念"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部12相应39经/思经第二(因缘相应/因缘篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，内心思考、计划做任何的事情，内心有烦恼产生或是有烦恼产生的趋势，「业识」（业识解释，见第六十七章）就会有存在和继续累积发展的根据地。当「业识」有根据地的时候，这个「业识」就有依靠的地方，就有立足点。当「业识」在根据地中持续的积累增长，那么「名色」就会产生、出现。什么是「名色」呢？精神、思想、心理就称为「名」，物质事物、身体就称为「色」。精神、思想、心理和物质事物，包括人或众生的身体就统称为「名色」。也就是说当「业识」在根据地中持续的积累增长的时候，就会产生、出现对物质和精神的挂念和执着，就会认为物质和精神是真实存在的，就会被物质和精神束缚捆绑。以「名色」为前提条件就会产生「六处」，以「六处」为前提条件就会产生「触」，以「触」为前提条件就会产生「受」，以「受」为前提条件就会产生「爱」，以「爱」为前提条件就会产生「取」，以「取」为前提条件就会产生「有」，以「有」为前提条件就会产生「生」，以「生」为前提条件就会产生忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。弟子们这就是世间人痛苦和烦恼产生、出现、聚集的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）的顺行。",-1),e("p",null,"弟子们，如果内心不思考、不计划做任何的事情，但是内心还有烦恼产生或是有烦恼产生的趋势，那么「业识」还是会有存在和继续累积发展的根据地。当「业识」有根据地的时候，这个「业识」还是会有依靠的地方，还是会有立足点。当「业识」在根据地中持续的积累增长，那么「名色」就会产生、出现。也就是说当「业识」在根据地中持续的积累增长的时候，就会产生、出现对物质和精神的挂念和执着，就会认为物质和精神是真实存在的，就会被物质和精神束缚捆绑。以「名色」为前提条件就会产生「六处」，以「六处」为前提条件就会产生「触」，以「触」为前提条件就会产生「受」，以「受」为前提条件就会产生「爱」，以「爱」为前提条件就会产生「取」，以「取」为前提条件就会产生「有」，以「有」为前提条件就会产生「生」，以「生」为前提条件就会产生忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。弟子们这就是世间人痛苦和烦恼产生、出现、聚集的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）的顺行。",-1),e("p",null,"弟子们，如果内心不思考、不计划做任何的事情，内心没有烦恼的产生，没有烦恼产生的趋势，那么「业识」就没有存在和继续累积发展的根据地。当「业识」没有根据地的时候，这个「业识」就没有依靠的地方，就没有立足点。「业识」就不会持续的积累增长，那么「名色」就不会产生、出现。也就是说当「业识」没有根据地，没有依靠的地方，没有立足点的时候，「业识」就不会持续的积累增长，这样就不会产生、出现对物质和精神的挂念和执着，就不会认为物质和精神是真实存在的，就不会被物质和精神束缚捆绑。「名色」除灭后就不会产生「六处」，「六处」除灭后就不会产生「触」，「触」除灭后就不会产生「受」，「受」除灭后就不会产生「爱」，「爱」除灭后就不会产生「取」，「取」除灭后就不会产生「有」，「有」除灭后就不会产生「生」，「生」除灭后就不会产生忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。弟子们这就是世间人痛苦和烦恼除灭的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）的逆行。",-1),e("p",null,"弟子们，缘起法的顺行就是错误的修行方法，缘起法的逆行就是正确的修行方法，你们应该按缘起法的逆行方法去修行。这样就能除灭你们一切的烦恼和痛苦，消除你们一切的罪业，最终让你们从生死轮回的煎熬和痛苦中永远的解脱出来。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
